# use bevy::prelude::*;
# use bevy_enhanced_input::prelude::*;
fn mock_jump(mut commands: Commands, jump: Single<Entity, With<Action<Jump>>>) {
    commands.entity(*jump).insert(ActionMock::once(TriggerState::Fired, true));
}
# #[derive(InputAction)]
# #[action_output(bool)]
# struct Jump;

