源码文档：Entities marked with this component will be disabled
upon exiting the given state.

```
use bevy_state::prelude::*;
use bevy_ecs::{prelude::*, system::ScheduleSystem};

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default, States)]
enum GameState {
    #[default]
    MainMenu,
    SettingsMenu,
    InGame,
}

# #[derive(Component)]
# struct Player;

fn spawn_player(mut commands: Commands) {
    commands.spawn((
        DisableOnExit(GameState::InGame),
        Player
    ));
}

# struct AppMock;
# impl AppMock {
#     fn init_state<S>(&mut self) {}
#     fn add_systems<S, M>(&mut self, schedule: S, systems: impl IntoScheduleConfigs<ScheduleSystem, M>) {}
# }
# struct Update;
# let mut app = AppMock;

app.init_state::<GameState>();
app.add_systems(OnEnter(GameState::InGame), spawn_player);
```

