#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default, States)]
enum GameState {
    #[default]
    MainMenu,
    SettingsMenu,
    InGame,
}

# #[derive(Component)]
# struct Player;

fn spawn_player(mut commands: Commands) {
    commands.spawn((
        DespawnOnExit(GameState::InGame),
        Player
    ));
}

